// PV7 (PV-45): a library on a customer bucket. The real media-worker router calls the real storage-worker handler as
// its STORAGE_WORKER binding, which talks to s3rver (an S3-compatible server in the test process). Uploads (single
// and multipart), downloads, purges and the pipeline's reads all go to the customer's bucket under its prefix;
// nothing lands in managed R2. Generated bytes only.

import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { randomBytes } from "node:crypto";
import { jest } from "@jest/globals";
import { UPLOAD_PART_SIZE } from "@saas/contracts/media";
import { remoteStore } from "@saas/shared/media-store";
import { clearRowCache, handle as storageHandle, type Env as StorageEnv } from "@storage-worker/index";
import { forgetStore } from "@media-worker/storage/stores";
import { FakeDigestStream, World, sha256hex, type User } from "./harness.js";

// A 32 MiB multipart upload goes through s3rver on disk; give it room when the suites run in parallel.
jest.setTimeout(60_000);

beforeAll(() => {
  (globalThis as unknown as { crypto: { DigestStream?: unknown } }).crypto.DigestStream = FakeDigestStream;
});

describe("a library on a customer bucket (through storage-worker)", () => {
  let server: { run(): Promise<{ port: number }>; close(): Promise<void> };
  let dir: string;
  let endpoint: string;

  beforeAll(async () => {
    dir = mkdtempSync(join(tmpdir(), "pv-byo-"));
    const S3rver = (await import("s3rver")).default as unknown as new (o: Record<string, unknown>) => typeof server;
    server = new S3rver({ port: 0, address: "127.0.0.1", silent: true, directory: dir, configureBuckets: [{ name: "team-bucket" }] });
    endpoint = `http://127.0.0.1:${(await server.run()).port}`;
  });
  afterAll(async () => {
    await server?.close();
    rmSync(dir, { recursive: true, force: true });
  });

  let w: World;
  let owner: User;
  let A: { id: string; pub: string; slug: string };
  let lib: { id: string };
  let base: string;
  let backendId: string;
  let libId: string;
  let sw: StorageEnv;
  const calls: string[] = [];

  beforeEach(async () => {
    w = new World();
    A = w.newOrg();
    owner = w.newUser("owner");
    w.grant(A, owner, "owner");
    lib = (await w.call(owner, "POST", `/v1/organizations/${A.pub}/libraries`, { name: "Shots" })).json.data.library;
    base = `/v1/organizations/${A.pub}/libraries/${lib.id}`;
    const hex = lib.id.replace(/^lib_/, "");
    libId = `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
    sw = { ENVIRONMENT: "test", PLATFORM_DB: w.env.PLATFORM_DB!, STORAGE_KEK: "c".repeat(64), ALLOW_TEST_ENDPOINTS: "true" };
    clearRowCache();
    calls.length = 0;
    w.env.STORAGE_WORKER = {
      fetch: (input: RequestInfo | URL, init?: RequestInit) => {
        const u = new URL(String(input));
        calls.push(`${u.searchParams.get("op") ?? init?.method ?? "GET"} ${u.searchParams.get("key") ?? ""}`);
        return storageHandle(new Request(String(input), init), sw);
      },
    } as unknown as Fetcher;
    // Attach the bucket through the library's storage API (PV-46).
    const created = await w.call(owner, "POST", `${base}/storage`, { endpoint, region: "us-east-1", bucket: "team-bucket", prefix: "pixvault", pathStyle: true, accessKeyId: "S3RVER", secretAccessKey: "S3RVER" });
    expect(created.status).toBe(201);
    const pubId: string = created.json.data.backend.id;
    const h = pubId.slice(4);
    backendId = `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20)}`;
    calls.length = 0;
    forgetStore();
  });

  async function upload(name: string, bytes: Uint8Array) {
    const s = (await w.call(owner, "POST", `${base}/uploads`, { name, size: bytes.length, sha256: sha256hex(bytes), mime: "application/octet-stream" })).json.data.session;
    for (let n = 1; n <= s.partCount; n++) {
      expect((await w.put(owner, `${base}/uploads/${s.id}/parts/${n}`, bytes.subarray((n - 1) * s.partSize, Math.min(n * s.partSize, bytes.length)))).status).toBe(200);
    }
    return w.call(owner, "POST", `${base}/uploads/${s.id}/commit`);
  }

  const bucketView = () => remoteStore({ fetch: (u, i) => storageHandle(new Request(u, i), sw) }, { orgId: A.id, libraryId: libId, backendId, prefix: "pixvault/" });

  it("single and multipart uploads land in the customer's bucket and download byte for byte", async () => {
    const small = randomBytes(4096);
    const c1 = await upload("a.bin", small);
    expect(c1.status).toBe(200);
    const big = randomBytes(UPLOAD_PART_SIZE + 7000);
    const c2 = await upload("big.bin", big);
    expect(c2.status).toBe(200);
    expect(c2.json.data.file).toMatchObject({ size: big.length, sha256: sha256hex(big) });

    // Nothing in managed R2; everything in the customer's bucket, under its prefix plus the library's managed key.
    expect(w.bucket.objects.size).toBe(0);
    expect(calls.some((c) => c.startsWith("uploadPart pixvault/org/"))).toBe(true);
    expect(calls.every((c) => c.split(" ")[1]!.startsWith(`pixvault/org/${A.id}/lib/${libId}/`))).toBe(true);

    const got = await w.bytes(owner, `${base}/files/${c1.json.data.file.id}/content`);
    expect(Buffer.from(got.bytes).equals(small)).toBe(true);
    const gotBig = await w.bytes(owner, `${base}/files/${c2.json.data.file.id}/content`);
    expect(sha256hex(gotBig.bytes)).toBe(sha256hex(big));
  });

  it("bytes that don't match their hash never become a file", async () => {
    const bytes = randomBytes(2048);
    const s = (await w.call(owner, "POST", `${base}/uploads`, { name: "x.bin", size: bytes.length, sha256: sha256hex(randomBytes(8)), mime: "application/octet-stream" })).json.data.session;
    const put = await w.put(owner, `${base}/uploads/${s.id}/parts/1`, bytes);
    expect(put.status).not.toBe(200);
    expect((await w.call(owner, "POST", `${base}/uploads/${s.id}/commit`)).status).not.toBe(200);
  });

  it("a purge deletes the object from the customer's bucket", async () => {
    const bytes = randomBytes(1500);
    const file = (await upload("p.bin", bytes)).json.data.file;
    const key = calls.find((c) => c.startsWith("PUT "))!.split(" ")[1]!.slice("pixvault/".length);
    expect(await bucketView().get(key)).not.toBeNull();
    await w.call(owner, "DELETE", `${base}/files/${file.id}`);
    expect((await w.call(owner, "DELETE", `${base}/files/${file.id}?permanent=1`)).status).toBe(200);
    expect(await bucketView().get(key)).toBeNull();
  });

  it("the library map tells serve-worker where the files are; a bucket that stops answering is a clear error", async () => {
    const updated = await w.call(owner, "PATCH", base, { name: "Shots 2" });
    expect(updated.status).toBe(200);
    const map = JSON.parse(w.kv.get(`lib:${A.slug}/${updated.json.data.library.slug}`)!);
    expect(map.b).toEqual({ i: backendId, p: "pixvault/" });

    const file = (await upload("q.bin", randomBytes(900))).json.data.file;
    w.db.prepare(`UPDATE media_storage_backends SET bucket = 'gone-bucket' WHERE id = ?`).run(backendId);
    clearRowCache();
    const r = await w.bytes(owner, `${base}/files/${file.id}/content`);
    expect(r.status).toBeGreaterThanOrEqual(500);
    expect(new TextDecoder().decode(r.bytes)).not.toContain("gone-bucket");
  });
});
